/**
 * @param {number[]} nums
 * @param {number} k
 * @return {void} Do not return anything, modify nums in-place instead.
 */
var rotate = function(nums, k) {
    const n = nums.length;
    if (n === 0) return;
    k %= n;
    const rev = (i, j) => {
        while (i < j) { [nums[i], nums[j]] = [nums[j], nums[i]]; i++; j--; }
    };
    rev(0, n - 1);
    rev(0, k - 1);
    rev(k, n - 1);
};

