    while (i <= hi) {
        if (nums[i] === 0) { [nums[lo], nums[i]] = [nums[i], nums[lo]]; lo++; i++; }
        else if (nums[i] === 2) { [nums[i], nums[hi]] = [nums[hi], nums[i]]; hi--; }
        else i++;
    }
};

