/**
 * @param {character[][]} grid
 * @return {number}
 */
var numIslands = function(grid) {
    const m = grid.length, n = m ? grid[0].length : 0;
    let count = 0;
    for (let i = 0; i < m; i++) {
        for (let j = 0; j < n; j++) {
            if (grid[i][j] !== "1") continue;
            count++;
            grid[i][j] = "0";
            const stack = [[i, j]];
            while (stack.length) {
                const [x, y] = stack.pop();
                for (const [dx, dy] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
                    const a = x + dx, b = y + dy;
                    if (a >= 0 && a < m && b >= 0 && b < n && grid[a][b] === "1") { grid[a][b] = "0"; stack.push([a, b]); }
                }
            }
        }
    }
    return count;
};

number-of-islands.java:
class Solution {
    public int numIslands(char[][] grid) {
        int m = grid.length, n = m > 0 ? grid[0].length : 0, count = 0;
        int[] dx = {1, -1, 0, 0}, dy = {0, 0, 1, -1};
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] != '1') continue;
                count++;
                grid[i][j] = '0';
                Deque<int[]> stack = new ArrayDeque<>();
                stack.push(new int[]{i, j});
                while (!stack.isEmpty()) {
                    int[] cur = stack.pop();
                    for (int d = 0; d < 4; d++) {
                        int a = cur[0] + dx[d], b = cur[1] + dy[d];
                        if (a >= 0 && a < m && b >= 0 && b < n && grid[a][b] == '1') { grid[a][b] = '0'; stack.push(new int[]{a, b}); }
                    }
                }
            }
        }
        return count;
    }
}
